    xs[0] + xs[1] * x + xs[2] * x^2 + ....
     Return derivative of this polynomial in the same form.
    >>> derivative([3, 1, 2, 4, 5])
    [1, 4, 12, 20]
    >>> derivative([1, 2, 3])
    [2, 6]
    """
    def derivative_helper(xs, k):
        if k == 0:
            return [1]
        else:
            return [k * xs[k] for x in xs] + derivative_helper(xs[1:], k - 1)

